def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def load_payload() -> dict[str, dict[str, str | None]]:
    raw = zlib.decompress(base64.b85decode(PAYLOAD_B85.encode('ascii')))
    return json.loads(raw.decode('utf-8'))


def repo_root() -> Path:
    root = Path.cwd().resolve()
    required = [
        root / 'settings.gradle.kts',
        root / 'app' / 'build.gradle.kts',
        root / 'CLAUDE.md',
        root / 'HANDOFF.md',
        root / 'ROADMAP.md',
    ]
    missing = [str(p.relative_to(root)) for p in required if not p.exists()]
    if missing:
        raise SystemExit(
            'Run this script from the Kinescope repository root. Missing: ' + ', '.join(missing)
        )
    return root


def preflight(root: Path, payload: dict[str, dict[str, str | None]]) -> tuple[list[str], list[str]]:
    to_write: list[str] = []
    already_done: list[str] = []
    conflicts: list[str] = []

    for rel, spec in payload.items():
        path = root / rel
        current = path.read_bytes() if path.is_file() else None
        current_sha = sha256(current) if current is not None else None
        old_sha = spec['old_sha256']
        new_sha = spec['new_sha256']

        if current_sha == new_sha:
            already_done.append(rel)
        elif current_sha == old_sha:
            to_write.append(rel)
        else:
            state = current_sha if current_sha is not None else '<missing>'
            conflicts.append(f'{rel}: unexpected SHA-256 {state}')

    if conflicts:
        details = '\n  - '.join(conflicts)
        raise SystemExit(
            'Preflight refused to modify the repository because one or more files do not match '            'either the exact Patch-24 baseline or the Patch-25 target. No files were changed.\n'
            f'  - {details}'
        )
    return to_write, already_done


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    fd, temp_name = tempfile.mkstemp(prefix=f'.{path.name}.', suffix='.patch25', dir=str(path.parent))
    try:
        with os.fdopen(fd, 'wb') as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temp_name, mode)
        os.replace(temp_name, path)
    except Exception:
        try:
            os.unlink(temp_name)
        except FileNotFoundError:
            pass
        raise


def apply_payload(root: Path, payload: dict[str, dict[str, str | None]], to_write: list[str]) -> None:
    for rel in to_write:
        spec = payload[rel]
        data = base64.b64decode(str(spec['new_b64']).encode('ascii'))
        if sha256(data) != spec['new_sha256']:
            raise RuntimeError(f'Embedded payload checksum mismatch for {rel}')
        atomic_write(root / rel, data)
        print(f'Updated: {rel}')


def verify_target_hashes(root: Path, payload: dict[str, dict[str, str | None]]) -> None:
    mismatches: list[str] = []
    for rel, spec in payload.items():
        path = root / rel
        if not path.is_file():
            mismatches.append(f'{rel} is missing')
            continue
        actual = sha256(path.read_bytes())
        if actual != spec['new_sha256']:
            mismatches.append(f'{rel} target hash mismatch: {actual}')
    if mismatches:
        raise RuntimeError('Post-write target verification failed:\n  - ' + '\n  - '.join(mismatches))


def scan_balanced_kotlin(text: str, path: str) -> None:
    """Small lexical balance check that ignores strings/comments."""
    stack: list[tuple[str, int]] = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set(pairs.values())
    i = 0
    state = 'code'
    while i < len(text):
        ch = text[i]
        nxt = text[i + 1] if i + 1 < len(text) else ''
        if state == 'code':
            if ch == '/' and nxt == '/':
                state = 'line_comment'; i += 2; continue
            if ch == '/' and nxt == '*':
                state = 'block_comment'; i += 2; continue
            if text.startswith('"""', i):
                state = 'triple_string'; i += 3; continue
            if ch == '"':
                state = 'string'; i += 1; continue
            if ch == "'":
                state = 'char'; i += 1; continue
            if ch in opens:
                stack.append((ch, i))
            elif ch in pairs:
                if not stack or stack[-1][0] != pairs[ch]:
                    raise RuntimeError(f'Unbalanced Kotlin delimiter {ch!r} in {path} at offset {i}')
                stack.pop()
            i += 1
            continue
        if state == 'line_comment':
            if ch == '\n': state = 'code'
            i += 1; continue
        if state == 'block_comment':
            if ch == '*' and nxt == '/': state = 'code'; i += 2
            else: i += 1
            continue
        if state == 'triple_string':
            if text.startswith('"""', i): state = 'code'; i += 3
            else: i += 1
            continue
        if state in ('string', 'char'):
            quote = '"' if state == 'string' else "'"
            if ch == '\\': i += 2; continue
            if ch == quote: state = 'code'
            i += 1
            continue
    if state in ('block_comment', 'triple_string', 'string', 'char'):
        raise RuntimeError(f'Unterminated {state} in {path}')
    if stack:
        opener, pos = stack[-1]
        raise RuntimeError(f'Unclosed Kotlin delimiter {opener!r} in {path} at offset {pos}')


def verify_static(root: Path) -> None:
    # XML well-formedness, including both localization files and manifest/icons.
    xml_files = sorted((root / 'app' / 'src' / 'main').rglob('*.xml'))
    for path in xml_files:
        ET.parse(path)

    def string_names(path: Path) -> set[str]:
        tree = ET.parse(path)
        names = [node.attrib['name'] for node in tree.getroot() if node.tag == 'string']
        if len(names) != len(set(names)):
            raise RuntimeError(f'Duplicate <string> names in {path}')
        return set(names)

    en_path = root / 'app/src/main/res/values/strings.xml'
    ru_path = root / 'app/src/main/res/values-ru/strings.xml'
    en = string_names(en_path)
    ru = string_names(ru_path)
    if en != ru:
        raise RuntimeError(
            'English/Russian string resource sets differ. '
            f'EN-only={sorted(en - ru)}, RU-only={sorted(ru - en)}'
        )

    kotlin_files = sorted((root / 'app/src/main/java').rglob('*.kt')) + sorted((root / 'app/src/test').rglob('*.kt'))
    resource_refs: set[str] = set()
    for path in kotlin_files:
        text = path.read_text(encoding='utf-8')
        scan_balanced_kotlin(text, str(path.relative_to(root)))
        resource_refs.update(re.findall(r'R\.string\.([A-Za-z0-9_]+)', text))
    missing_resources = sorted(resource_refs - en)
    if missing_resources:
        raise RuntimeError('Missing English string resources: ' + ', '.join(missing_resources))

    manifest = (root / 'app/src/main/AndroidManifest.xml').read_text(encoding='utf-8')
    if 'android:allowBackup="false"' not in manifest:
        raise RuntimeError('Android backup must remain disabled while private session/log/job data exists')

    workflow = root / '.github/workflows/build-release.yml'
    workflow_text = workflow.read_text(encoding='utf-8')
    required_workflow_markers = [
        'testDebugUnitTest lintDebug assembleRelease',
        'apksigner',
        'zipalign',
        "package: name='com.kinescope.app'",
        'args=(release create',
    ]
    for marker in required_workflow_markers:
        if marker not in workflow_text:
            raise RuntimeError(f'Release workflow lost required marker: {marker}')
    if (root / '.github/workflows/build-debug.yml').exists():
        raise RuntimeError('Debug GitHub Actions workflow must remain deleted after patch 24')

    if (root / 'roadmap.md').exists():
        raise RuntimeError('Lowercase roadmap.md must remain deleted; ROADMAP.md is the single source of truth')
    if not (root / 'THIRD_PARTY_NOTICES.md').is_file():
        raise RuntimeError('THIRD_PARTY_NOTICES.md is missing')

    roadmap = (root / 'ROADMAP.md').read_text(encoding='utf-8')
    if '## Remaining verification gates' not in roadmap or '## What patch 25 closes' not in roadmap:
        raise RuntimeError('ROADMAP.md does not contain the finalized Patch-25 state')
    handoff = (root / 'HANDOFF.md').read_text(encoding='utf-8')
    if 'Next work is verification, not another autonomous roadmap sprint.' not in handoff:
        raise RuntimeError('HANDOFF.md does not contain the final session handoff marker')
    changelog = (root / 'CHANGELOG.md').read_text(encoding='utf-8')
    if '## Patch 25 — Reliability roadmap completion and release hardening' not in changelog:
        raise RuntimeError('CHANGELOG.md does not contain Patch 25')

    test_dir = root / 'app/src/test/java/com/kinescope/app'
    required_tests = {
        'YouTubeUrlParserTest.kt',
        'DownloadErrorClassifierTest.kt',
        'DiagnosticSanitizerTest.kt',
    }
    existing_tests = {p.name for p in test_dir.glob('*.kt')} if test_dir.is_dir() else set()
    if not required_tests <= existing_tests:
        raise RuntimeError('Required Patch-25 JVM tests are missing: ' + ', '.join(sorted(required_tests - existing_tests)))

    print(f'Static verification: OK ({len(xml_files)} XML files, {len(kotlin_files)} Kotlin/test files, {len(en)} localized strings)')


def run_gradle_gate(root: Path) -> None:
    if os.environ.get('KINESCOPE_PATCH25_TEST_MODE') == '1':
        print('Gradle gate skipped only because KINESCOPE_PATCH25_TEST_MODE=1 (patch-script regression mode).')
        return
    gradlew = root / 'gradlew'
    if not gradlew.is_file():
        raise RuntimeError('gradlew is missing; cannot verify Patch 25')
    if not os.access(gradlew, os.X_OK):
        gradlew.chmod(gradlew.stat().st_mode | 0o111)
    print('Running Gradle verification: testDebugUnitTest + lintDebug + assembleDebug ...')
    subprocess.run(
        [str(gradlew), '--no-daemon', 'testDebugUnitTest', 'lintDebug', 'assembleDebug'],
        cwd=root,
        check=True,
    )
    print('Gradle verification: OK')


def delete_self_after_success(root: Path) -> None:
    if os.environ.get('KINESCOPE_PATCH25_TEST_MODE') == '1':
        return
    script = Path(__file__).resolve()
    try:
        script.relative_to(root)
    except ValueError:
        print(f'Patch succeeded, but script is outside the repo and was not deleted: {script}')
        return
    script.unlink()
    print(f'Removed patch script: {script.name}')


def main() -> None:
    root = repo_root()
    payload = load_payload()
    to_write, already_done = preflight(root, payload)
    if already_done:
        print(f'Already at Patch-25 target: {len(already_done)} file(s)')
    if to_write:
        print(f'Applying {PATCH_NAME} to {len(to_write)} file(s) ...')
        apply_payload(root, payload, to_write)
    else:
        print('No file writes needed; repository already matches Patch 25 target.')

    verify_target_hashes(root, payload)
    verify_static(root)
    run_gradle_gate(root)
    delete_self_after_success(root)
    print('Patch 25 / roadmap completion: SUCCESS')


if __name__ == '__main__':
    try:
        main()
    except subprocess.CalledProcessError as exc:
        print(f'Patch files were applied, but Gradle verification failed with exit code {exc.returncode}.', file=sys.stderr)
        print('The patch script was intentionally kept in the repo. Fix the reported build/lint/test issue and rerun it.', file=sys.stderr)
        raise SystemExit(exc.returncode)
    except Exception as exc:
        print(f'{PATCH_NAME} failed: {exc}', file=sys.stderr)
        print('The patch script was intentionally kept in place.', file=sys.stderr)
        raise SystemExit(1)
